  /** Apply an invitation to an existing group and enqueue autonomous AI resolution when needed. */
  public async commitModelInvite(input: { intentionId: string; sessionId: string; channelId: string; actorId: string; targetActorId: string }): Promise<{ membership: SocialMembership; createdIntentions: SocialIntention[] }> { return this.opened.db.transaction().execute(async (trx) => { const channel = await trx.selectFrom('socialChannels').selectAll().where('id', '=', input.channelId).where('sessionId', '=', input.sessionId).executeTakeFirstOrThrow(); if (channel.kind !== 'group') throw new Error('Only group channels support invitations'); await this.assertActiveMember(trx, input.channelId, input.actorId); await this.assertActorsInSession(trx, input.sessionId, [input.targetActorId]); const existing = await trx.selectFrom('socialMemberships').select('id').where('channelId', '=', input.channelId).where('actorId', '=', input.targetActorId).where('status', 'in', ['active', 'invited']).executeTakeFirst(); if (existing) throw new Error('Actor is already a member or invitee'); const now = new Date().toISOString(); const membership = await trx.insertInto('socialMemberships').values({ id: randomUUID(), channelId: input.channelId, actorId: input.targetActorId, status: 'invited', invitedByActorId: input.actorId, visibleAfterMessageId: await this.latestMessageId(trx, input.channelId), leftAfterMessageId: null, createdAt: now, updatedAt: now }).returningAll().executeTakeFirstOrThrow(); await this.completeRunningIntention(trx, input.intentionId, 'invite_actor', now); const actor = await trx.selectFrom('socialActors').selectAll().where('id', '=', input.targetActorId).executeTakeFirstOrThrow(); const createdIntentions = actor.control === 'model' && actor.status === 'active' ? [await this.insertIntention(trx, { id: randomUUID(), actorId: input.targetActorId, kind: 'invitation-decision', channelId: input.channelId, sourceMessageId: null, priority: 90, state: 'queued', notBefore: now, payload: JSON.stringify({ channelId: input.channelId, channelTitle: channel.title, inviterActorId: input.actorId, membershipId: membership.id }), dedupeKey: `invitation-decision:${membership.id}`, cascadeId: null, operationClass: 'invitation' }, now)] : []; return { membership: this.toMembership(membership), createdIntentions: createdIntentions.map((row) => this.toIntention(row)) }; }); }
  /** Apply an actor-owned memory update and complete the intention atomically with CAS validation. */
  public async commitMemoryDecision(input: { intentionId: string; actorId: string; content: string; expectedRevision: number }): Promise<SocialMemory> { const now = new Date().toISOString(); return this.opened.db.transaction().execute(async (trx) => { const current = await trx.selectFrom('socialMemories').selectAll().where('actorId', '=', input.actorId).executeTakeFirst(); const revision = current?.revision ?? 0; if (revision !== input.expectedRevision) throw new Error(`Memory revision conflict for ${input.actorId}: expected ${input.expectedRevision}, current ${revision}`); const memory = current ? await trx.updateTable('socialMemories').set({ revision: revision + 1, content: input.content, updatedAt: now, sourceRunId: input.intentionId }).where('actorId', '=', input.actorId).where('revision', '=', revision).returningAll().executeTakeFirstOrThrow() : await trx.insertInto('socialMemories').values({ actorId: input.actorId, revision: 1, content: input.content, updatedAt: now, sourceRunId: input.intentionId }).returningAll().executeTakeFirstOrThrow(); await this.completeRunningIntention(trx, input.intentionId, 'update_memory', now); return { ...memory }; }); }
  /** Read only messages visible during the actor's active membership periods. */
  public async readMessages(sessionId: string, channelId: string, actorId: string, limit = 100, beforeId?: number, inspect = false): Promise<VisibleMessagePage> {
    limit = Math.max(1, Math.min(200, Math.floor(limit)));
    let query = this.opened.db.selectFrom('socialMessages as msg').innerJoin('socialChannels as channel', 'channel.id', 'msg.channelId').selectAll('msg').where('channel.sessionId', '=', sessionId).where('msg.channelId', '=', channelId);
    if (!inspect) query = query.where((eb) => eb.exists(eb.selectFrom('socialMemberships as member').select('member.id').whereRef('member.channelId', '=', 'msg.channelId').where('member.actorId', '=', actorId).where('member.status', 'in', ['active', 'left']).whereRef('member.visibleAfterMessageId', '<', 'msg.id').where((inner) => inner.or([inner('member.leftAfterMessageId', 'is', null), inner('member.leftAfterMessageId', '>=', eb.ref('msg.id'))]))));
    if (beforeId !== undefined) query = query.where('msg.id', '<', beforeId);
    const rows = await query.orderBy('msg.id', 'desc').limit(limit + 1).execute(); return { messages: rows.slice(0, limit).reverse().map((row) => this.toMessage(row)), hasMore: rows.length > limit };
  }
  /** Replace an actor's private memory with a new revision. */
